{
  "lines": [
    {
      "id": "plan.complete",
      "tiers": [
        {
          "id": "plan.complete:t1",
          "title": "Маршрут ожил",
          "phrase": "Ты выполнил первую тренировку по исходному плану, не снижая цели задним числом. У бумажного маршрута появились следы твоих кроссовок.",
          "imagePrompt": "A lively rolled-paper route map with little gloved hands and hiking boots steps onto a low finish platform beside a tiny dumbbell. Its loose paper tail stretches back across a simple winding path.",
          "fishMarkup": "[warm]Ты выполнил первую тренировку по исходному плану, не снижая цели задним числом. У бумажного маршрута появились <soft>следы твоих кроссовок.</soft>",
          "audioText": "Ты выполнил первую тренировку по исходному плану, не снижая цели задним числом. У бумажного маршрута появились следы твоих кроссовок."
        },
        {
          "id": "plan.complete:t2",
          "title": "Бумажный попутчик",
          "phrase": "В твоей истории 5 тренировок по исходному плану без снижения целей задним числом. Ты превратил план из бумажки в бывалого попутчика.",
          "imagePrompt": "The same rolled-paper map explorer climbs a staircase built from closed workout folders, hauling a compact backpack. A long accordion-folded route spills from the pack and neatly follows every step below.",
          "fishMarkup": "[confident]В твоей истории <emphasis>5 тренировок</emphasis> по исходному плану без снижения целей задним числом. Ты превратил план из бумажки в бывалого попутчика.",
          "audioText": "В твоей истории 5 тренировок по исходному плану без снижения целей задним числом. Ты превратил план из бумажки в бывалого попутчика."
        },
        {
          "id": "plan.complete:t3",
          "title": "План пишет мемуары",
          "phrase": "Ты выполнил 15 тренировок по исходному плану без снижения целей задним числом. План сел писать мемуары — разумеется, о тебе.",
          "imagePrompt": "The same rolled-paper map perches on a tower of workout folders at an enormous blank open book. It grips an absurdly oversized quill like a grand biographer, while a tiny dumbbell holds a curling page flat.",
          "fishMarkup": "[triumphant]Ты выполнил <emphasis>15 тренировок</emphasis> по исходному плану без снижения целей задним числом. План сел писать мемуары — <slow>разумеется, о тебе.</slow>",
          "audioText": "Ты выполнил 15 тренировок по исходному плану без снижения целей задним числом. План сел писать мемуары — разумеется, о тебе."
        }
      ]
    },
    {
      "id": "plan.exercise",
      "tiers": [
        {
          "id": "plan.exercise:t1",
          "title": "Первые крепкие стыки",
          "phrase": "Ты завершил 5 упражнений: все обязательные подходы выполнены по исходным целям. Первые кирпичики на месте — прораб-бобр одобряет.",
          "imagePrompt": "A beaver carpenter in a hard hat assembles a small wooden dumbbell on a low workbench. One paw steadies the handle while the other taps a squared weight block into place with a wooden mallet.",
          "fishMarkup": "[warm]Ты завершил 5 упражнений: все обязательные подходы выполнены по исходным целям. Первые кирпичики на месте — <soft>прораб-бобр одобряет.</soft>",
          "audioText": "Ты завершил 5 упражнений: все обязательные подходы выполнены по исходным целям. Первые кирпичики на месте — прораб-бобр одобряет."
        },
        {
          "id": "plan.exercise:t2",
          "title": "Стройка набрала ход",
          "phrase": "В твоей копилке 20 упражнений со всеми обязательными подходами по исходным целям. Ты строишь историю — у прораба-бобра уже каска подпрыгивает.",
          "imagePrompt": "The same beaver carpenter operates a hand-cranked hoist beside a huge wooden dumbbell under construction. A squared weight block rises toward the handle, scaffolding hugs both ends, and the beaver's hard hat bounces above its head.",
          "fishMarkup": "[confident]В твоей копилке <emphasis>20 упражнений</emphasis> со всеми обязательными подходами по исходным целям. Ты строишь историю — у прораба-бобра уже каска подпрыгивает.",
          "audioText": "В твоей копилке 20 упражнений со всеми обязательными подходами по исходным целям. Ты строишь историю — у прораба-бобра уже каска подпрыгивает."
        },
        {
          "id": "plan.exercise:t3",
          "title": "Гантельная прописка",
          "phrase": "За это время ты завершил 60 упражнений со всеми обязательными подходами по исходным целям. Бобр сдал гантельный дворец — и тут же заселился.",
          "imagePrompt": "The same beaver carpenter relaxes in a hammock inside a colossal wooden dumbbell turned into a house. Its handle forms a porch between two blocky weight rooms; a mallet and hard hat rest beside the doorway.",
          "fishMarkup": "[triumphant]За это время ты завершил <emphasis>60 упражнений</emphasis> со всеми обязательными подходами по исходным целям. Бобр сдал гантельный дворец — <slow>и тут же заселился.</slow>",
          "audioText": "За это время ты завершил 60 упражнений со всеми обязательными подходами по исходным целям. Бобр сдал гантельный дворец — и тут же заселился."
        }
      ]
    }
  ]
}
